const b = $json.body || $json;
const from = String(b.from || b.whatsapp || '').trim();
const negocio = String(b.negocio || '').trim();
const text = String(b.text || '').trim();
const equipo = String(b.equipo_wasap || b.aviso_a || '').trim();
return [{ json: {
  ok: true,
  sistema: '09-wasap-task-faq-citas',
  etapa: 'handoff',
  from, negocio, text,
  reply_cliente: 'Te derivo con una persona del equipo. En un momento te escriben.',
  aviso_equipo: equipo ? `Handoff de ${from}: ${text || '(sin texto)'}` : null,
  status: 'draft_ready',
  todo: 'TODO_CREDENCIAL: mensaje al cliente + aviso interno',
  at: new Date().toISOString()
}}];
